INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Müssen Auszubildende aktiv bei der Planung ihrer Ausbildung mitwirken?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG verpflichtet zur Mitwirkung"}, {"text": "Nein", "correct": false, "because": "Mitwirkung ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Auszubildende die Ausbildungsplanung komplett dem Arbeitgeber überlassen?', 2, '[{"text": "Ja", "correct": false, "because": "§ 13 BBiG fordert aktive Mitwirkung"}, {"text": "Nein", "correct": true, "because": "Mitwirkung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Mitwirkung bei der Ausbildungsplanung eine freiwillige Aufgabe von Auszubildenden?', 2, '[{"text": "Ja", "correct": false, "because": "Sie ist gesetzlich verpflichtend nach § 13 BBiG"}, {"text": "Nein", "correct": true, "because": "Pflicht gemäß BBiG"}]'),
('00000000-0000-0000-0000-000000000000', 'Haben Auszubildende das Recht, bei der Ausbildungsplanung Vorschläge einzubringen?', 2, '[{"text": "Ja", "correct": true, "because": "Mitwirkung umfasst auch Vorschläge (§ 13 BBiG)"}, {"text": "Nein", "correct": false, "because": "Vorschläge sind Teil der Mitwirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Verstoß gegen die Mitwirkungspflicht Konsequenzen für Auszubildende haben?', 2, '[{"text": "Ja", "correct": true, "because": "Pflichtverletzung kann sanktioniert werden"}, {"text": "Nein", "correct": false, "because": "Verstoß kann Folgen haben"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was regelt § 13 BBiG bezüglich der Mitwirkung bei der Ausbildungsplanung?', 2, '[{"text": "Pflicht der Auszubildenden zur aktiven Beteiligung", "correct": true, "because": "§ 13 BBiG definiert diese Pflicht"}, {"text": "Recht des Arbeitgebers zur alleinigen Planung", "correct": false, "because": "Mitwirkung ist vorgeschrieben"}, {"text": "Freiwillige Teilnahme an Prüfungen", "correct": false, "because": "Falsches Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist primär für die Erstellung des Ausbildungsplans verantwortlich?', 3, '[{"text": "Der Arbeitgeber", "correct": true, "because": "§ 11 BBiG legt die Verantwortung beim Arbeitgeber, Auszubildende wirken mit"}, {"text": "Die Auszubildenden", "correct": false, "because": "Sie wirken nur mit"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule plant nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe haben Auszubildende bei der Ausbildungsplanung?', 2, '[{"text": "Aktive Mitwirkung", "correct": true, "because": "§ 13 BBiG fordert Mitwirkung"}, {"text": "Kontrolle der Arbeitszeiten", "correct": false, "because": "Anderes Thema"}, {"text": "Festlegung der Vergütung", "correct": false, "because": "Nicht ihre Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei fehlender Mitwirkung eines Auszubildenden?', 3, '[{"text": "Verwarnung oder Kündigung", "correct": true, "because": "Pflichtverletzung kann sanktioniert werden"}, {"text": "Höhere Vergütung", "correct": false, "because": "Keine Belohnung"}, {"text": "Weniger Urlaub", "correct": false, "because": "Keine direkte Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundlage verpflichtet Auszubildende zur Mitwirkung?', 2, '[{"text": "Berufsbildungsgesetz (§ 13 BBiG)", "correct": true, "because": "Gesetzliche Regelung"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "Kündigungsschutzgesetz", "correct": false, "because": "Regelt Kündigung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeiten gehören zur Mitwirkung bei der Ausbildungsplanung?', 4, '[{"text": "Vorschläge zur Gestaltung einbringen", "correct": true, "because": "Teil der Mitwirkung"}, {"text": "Einhaltung der Arbeitszeit kontrollieren", "correct": false, "because": "Andere Pflicht"}, {"text": "Rückmeldung zu Lernfortschritten geben", "correct": true, "because": "Fördert Planung"}, {"text": "Ausbildungsziele mitdefinieren", "correct": true, "because": "Aktive Beteiligung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen kann fehlende Mitwirkung bei der Ausbildungsplanung haben?', 3, '[{"text": "Verwarnung durch den Ausbilder", "correct": true, "because": "Sanktion möglich"}, {"text": "Verzögerung der Ausbildung", "correct": true, "because": "Planung leidet"}, {"text": "Höhere Vergütung", "correct": false, "because": "Keine Belohnung"}, {"text": "Kündigung bei wiederholtem Verstoß", "correct": true, "because": "Schwere Pflichtverletzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten neben der Mitwirkung regelt § 13 BBiG?', 4, '[{"text": "Lernpflichten erfüllen", "correct": true, "because": "§ 13 BBiG umfasst dies"}, {"text": "Arbeitszeit einhalten", "correct": true, "because": "Teil der Pflichten"}, {"text": "Vergütung aushandeln", "correct": false, "because": "Nicht in § 13 BBiG"}, {"text": "Sorgfalt bei der Arbeit", "correct": true, "because": "Ebenfalls in § 13 BBiG"}]'),
('00000000-0000-0000-0000-000000000000', 'Was fördert die Mitwirkung der Auszubildenden bei der Ausbildungsplanung?', 3, '[{"text": "Individuelle Anpassung der Ausbildung", "correct": true, "because": "Berücksichtigt Bedürfnisse"}, {"text": "Effektive Zielerreichung", "correct": true, "because": "Planung wird optimiert"}, {"text": "Höhere Kosten für den Betrieb", "correct": false, "because": "Kein Effekt"}, {"text": "Bessere Zusammenarbeit", "correct": true, "because": "Kooperation wird gestärkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielen Auszubildende und Arbeitgeber bei der Ausbildungsplanung?', 3, '[{"text": "Arbeitgeber erstellt den Plan", "correct": true, "because": "§ 11 BBiG"}, {"text": "Auszubildende wirken mit", "correct": true, "because": "§ 13 BBiG"}, {"text": "Berufsschule übernimmt die Planung", "correct": false, "because": "Nicht deren Aufgabe"}, {"text": "Auszubildende haben Mitspracherecht", "correct": true, "because": "Teil der Mitwirkung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Auszubildende müssen bei der Ausbildungsplanung mitwirken. b) Der Arbeitgeber hat keine Rolle bei der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) § 13 BBiG, b) ist falsch (§ 11 BBiG)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mitwirkung bedeutet aktive Beteiligung. b) Auszubildende können die Planung ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig (§ 13 BBiG), b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mitwirkung kann die Ausbildung verbessern. b) Sie ist keine Pflicht gemäß BBiG.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (§ 13 BBiG)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Auszubildende dürfen Vorschläge machen. b) Die Mitwirkungspflicht gilt nur für Arbeitgeber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig (§ 13 BBiG), b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlende Mitwirkung kann sanktioniert werden. b) Auszubildende gestalten den Plan allein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (§ 11 BBiG)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
